namespace NotificationApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(NextId(), "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving at random.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            var messages = new[]
            {
                "Server CPU spike detected.",
                "Deployment completed successfully.",
                "New user signed up.",
                "Backup finished.",
                "Disk usage above 80%.",
                "Payment received.",
                "Scheduled maintenance at midnight.",
            };

            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li>
                <strong>@n.Message</strong>
                <span class="timestamp">@n.Timestamp.ToString("HH:mm:ss")</span>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? _notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch when restored from prerender state.
        _notifications ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is NOT called during prerender — only after the
        // interactive runtime attaches, so the polling loop never runs
        // during the static SSR pass.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        try
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                // Simulate a new notification arriving on the server side.
                NotificationService.SimulateIncoming();

                int lastId = _notifications?.Count > 0
                    ? _notifications.Max(n => n.Id)
                    : 0;

                var newer = await NotificationService.GetNotificationsSinceAsync(lastId);
                if (newer.Count > 0)
                {
                    _notifications ??= new();
                    _notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
        }
        catch (TaskCanceledException)
        {
            // Expected on dispose — exit cleanly.
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

